import { COLORS, FONT_DISPLAY, FONT_BODY, FONT_MONO } from "./theme.js";

const MESES_ABREV = ["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];
const MESES_LONGO = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];

const STORAGE_KEY = "isp-sales-records-v1";
const LOG_KEY = "isp-import-log-v1";

function parseValorBR(v) {
  if (v === undefined || v === null || v === "" || v === "-") return 0;
  if (typeof v === "number") return v;
  const cleaned = String(v).trim().replace(/\./g, "").replace(",", ".");
  const n = parseFloat(cleaned);
  return isNaN(n) ? 0 : n;
}

function monthKeyFromBR(dv) {
  if (!dv || typeof dv !== "string") return null;
  const m = dv.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!m) return null;
  return `${m[3]}-${m[2]}`;
}

function monthLabel(key, long) {
  if (!key) return "";
  const [y, m] = key.split("-");
  const idx = parseInt(m, 10) - 1;
  const name = long ? MESES_LONGO[idx] : MESES_ABREV[idx];
  return long ? `${name} de ${y}` : `${name}/${y.slice(2)}`;
}

function fmtBRL(v) {
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(v || 0);
}
function fmtBRLFull(v) {
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v || 0);
}
function fmtInt(v) {
  return new Intl.NumberFormat("pt-BR").format(v || 0);
}

const HEADER_MAP = {
  codigo_cliente: "c", nome_razaosocial: "n", vendedor: "v", valor: "valFallback",
  valor_com_pacote: "val", data_venda: "dv", servico_status: "st",
  situacao_contrato: "sc", tecnologia: "tec", servico: "srv",
};

function parseWorkbookToRecords(workbook) {
  const sheetName = workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: false, defval: "" });
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || "").trim().toLowerCase());
  const colIndex = {};
  headers.forEach((h, i) => {
    if (HEADER_MAP[h]) colIndex[HEADER_MAP[h]] = i;
  });
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row.length) continue;
    const codigo = colIndex.c !== undefined ? row[colIndex.c] : null;
    if (!codigo && codigo !== 0) continue;
    const valorPrincipal = colIndex.val !== undefined ? row[colIndex.val] : undefined;
    const valorFallback = colIndex.valFallback !== undefined ? row[colIndex.valFallback] : undefined;
    const valor = parseValorBR(valorPrincipal !== undefined && valorPrincipal !== "" ? valorPrincipal : valorFallback);
    out.push({
      c: String(codigo),
      n: colIndex.n !== undefined ? String(row[colIndex.n] || "").slice(0, 40) : "",
      v: colIndex.v !== undefined ? String(row[colIndex.v] || "-") : "-",
      val: Math.round(valor * 100) / 100,
      dv: colIndex.dv !== undefined ? String(row[colIndex.dv] || "") || null : null,
      st: colIndex.st !== undefined ? String(row[colIndex.st] || "-") : "-",
      sc: colIndex.sc !== undefined ? String(row[colIndex.sc] || "-") : "-",
      tec: colIndex.tec !== undefined ? String(row[colIndex.tec] || "-") : "-",
      srv: colIndex.srv !== undefined ? String(row[colIndex.srv] || "-") : "-",
    });
  }
  return out;
}

function mergeRecords(existing, incoming) {
  const map = new Map(existing.map((r) => [r.c, r]));
  let added = 0, updated = 0;
  incoming.forEach((r) => {
    if (map.has(r.c)) updated++; else added++;
    map.set(r.c, r);
  });
  return { merged: Array.from(map.values()), added, updated };
}

function Toggle({ options, value, onChange }) {
  return (
    <div style={{ display: "inline-flex", background: COLORS.tealSoft, borderRadius: 8, padding: 3, gap: 2 }}>
      {options.map((opt) => (
        <button
          key={opt.value}
          onClick={() => onChange(opt.value)}
          style={{
            fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600, padding: "6px 14px",
            borderRadius: 6, border: "none", cursor: "pointer",
            background: value === opt.value ? COLORS.teal : "transparent",
            color: value === opt.value ? "#fff" : COLORS.tealDark,
            transition: "background 0.15s ease",
          }}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

function KpiCard({ icon: Icon, label, value, sub, accent }) {
  return (
    <div style={{
      background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10,
      padding: "18px 20px", flex: "1 1 200px", minWidth: 190,
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <div style={{
          width: 28, height: 28, borderRadius: 7, background: accent + "1A",
          display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          <Icon size={15} color={accent} strokeWidth={2.2} />
        </div>
        <span style={{ fontFamily: FONT_BODY, fontSize: 12.5, color: COLORS.inkMuted, fontWeight: 500 }}>{label}</span>
      </div>
      <div style={{ fontFamily: FONT_MONO, fontSize: 26, fontWeight: 600, color: COLORS.ink, letterSpacing: "-0.5px" }}>
        {value}
      </div>
      {sub && <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: COLORS.inkMuted, marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

function CheckboxPill({ label, checked, onClick, color }) {
  return (
    <button
      onClick={onClick}
      style={{
        display: "inline-flex", alignItems: "center", gap: 6, fontFamily: FONT_BODY, fontSize: 12.5,
        padding: "5px 10px 5px 8px", borderRadius: 7, cursor: "pointer",
        border: `1px solid ${checked ? (color || COLORS.teal) : COLORS.border}`,
        background: checked ? (color ? color + "14" : COLORS.tealSoft) : "#fff",
        color: checked ? COLORS.ink : COLORS.inkMuted, fontWeight: 500, transition: "all 0.12s ease",
      }}
    >
      <span style={{
        width: 14, height: 14, borderRadius: 4, border: `1.5px solid ${checked ? (color || COLORS.teal) : COLORS.borderStrong}`,
        background: checked ? (color || COLORS.teal) : "transparent",
        display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      }}>
        {checked && <Check size={10} color="#fff" strokeWidth={3} />}
      </span>
      {label}
    </button>
  );
}

